/* full SVG string for an icon (black strokes; used as a CSS mask) */
export function iconSvg(name) {
  const parts = ICONS[name];
  if (!parts) return null;
  const body = parts.map(([d, s]) => (S[s] === 'FILL' ? `<path d="${d}" fill="#000"/>` : `<path d="${d}" stroke="#000" ${S[s]}/>`)).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none">${body}</svg>`;
}
const cache = {};
/* data: URL for a library icon, or the path itself when it's already a file URL */
export function iconUrl(nameOrUrl) {
  if (nameOrUrl.startsWith('/')) return nameOrUrl;
  if (!cache[nameOrUrl]) { const svg = iconSvg(nameOrUrl); cache[nameOrUrl] = svg ? 'data:image/svg+xml;utf8,' + encodeURIComponent(svg) : ''; }
  return cache[nameOrUrl];
}
export const ICON_NAMES = Object.keys(ICONS);
